#include <iostream>
#include <vector>
struct MyClass {
  std::vector<int> data;
  MyClass() { std::cout << "Constructor called\n"; }
  MyClass(const MyClass& other) { data = other.data; std::cout << "Copy constructor called\n"; }
  MyClass(MyClass&& other) noexcept { data = std::move(other.data); std::cout << "Move constructor called\n"; }
};
MyClass myFunction() {
  MyClass obj;
  obj.data.push_back(1);
  obj.data.push_back(2);
  return obj;
}
int main() {
  MyClass result = myFunction();
  return 0;
}
